const API_URL = "http://localhost:5000/api";


// ============================================================
// SIGNUP
// ============================================================

export async function signup(data) {
    const response = await fetch(
        `${API_URL}/auth/signup`,
        {
            method: "POST",

            headers: {
                "Content-Type": "application/json",
            },

            body: JSON.stringify(data),
        }
    );

    return await response.json();
}


// ============================================================
// LOGIN
// ============================================================

